-- The hosted database had the first three statements of the original Phase 4
-- migration applied before its no-op ALTER failed. Complete that foundation
-- idempotently, then let the following Phase 4A migration add lifecycle RPCs.
do $$ begin create type public.business_document_status as enum ('draft','posted','reversed'); exception when duplicate_object then null; end $$;
do $$ begin create type public.open_item_kind as enum ('receivable','payable'); exception when duplicate_object then null; end $$;
do $$ begin create type public.open_item_status as enum ('open','partial','settled'); exception when duplicate_object then null; end $$;
create table if not exists public.customers (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),name text not null,trn text,email text,phone text,billing_address text,payment_terms_days integer not null default 30 check(payment_terms_days>=0),is_active boolean not null default true,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,name));
create table if not exists public.suppliers (like public.customers including all);
create table if not exists public.sales_invoices (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),branch_id uuid references public.branches(id),customer_id uuid not null references public.customers(id),invoice_number text,invoice_date date not null,due_date date not null,reference text,notes text,status public.business_document_status not null default 'draft',subtotal numeric(20,6) not null default 0,tax_total numeric(20,6) not null default 0,grand_total numeric(20,6) not null default 0,posted_journal_id uuid references public.journal_entries(id),posted_at timestamptz,posted_by uuid references auth.users(id),created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,invoice_number));
create table if not exists public.sales_invoice_lines (id uuid primary key default gen_random_uuid(),invoice_id uuid not null references public.sales_invoices(id) on delete cascade,organization_id uuid not null references public.organizations(id),description text not null,quantity numeric(20,6) not null check(quantity>0),unit_price numeric(20,6) not null check(unit_price>=0),discount numeric(20,6) not null default 0 check(discount>=0),tax_rate_id uuid references public.tax_rates(id),revenue_account_id uuid references public.accounts(id),created_at timestamptz not null default now());
create table if not exists public.purchase_bills (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),branch_id uuid references public.branches(id),supplier_id uuid not null references public.suppliers(id),bill_number text,bill_date date not null,due_date date not null,reference text,notes text,status public.business_document_status not null default 'draft',subtotal numeric(20,6) not null default 0,tax_total numeric(20,6) not null default 0,grand_total numeric(20,6) not null default 0,posted_journal_id uuid references public.journal_entries(id),posted_at timestamptz,posted_by uuid references auth.users(id),created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,bill_number));
create table if not exists public.purchase_bill_lines (id uuid primary key default gen_random_uuid(),bill_id uuid not null references public.purchase_bills(id) on delete cascade,organization_id uuid not null references public.organizations(id),description text not null,quantity numeric(20,6) not null check(quantity>0),unit_price numeric(20,6) not null check(unit_price>=0),discount numeric(20,6) not null default 0 check(discount>=0),tax_rate_id uuid references public.tax_rates(id),expense_account_id uuid not null references public.accounts(id),created_at timestamptz not null default now());
create table if not exists public.open_items (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),kind public.open_item_kind not null,customer_id uuid references public.customers(id),supplier_id uuid references public.suppliers(id),source_journal_id uuid not null references public.journal_entries(id),source_document_id uuid not null,original_amount numeric(20,6) not null check(original_amount>0),due_date date,status public.open_item_status not null default 'open',created_at timestamptz not null default now(),check((kind='receivable' and customer_id is not null and supplier_id is null) or (kind='payable' and supplier_id is not null and customer_id is null)),unique(source_journal_id));
do $$ declare t text; begin foreach t in array array['customers','suppliers','sales_invoices','sales_invoice_lines','purchase_bills','purchase_bill_lines','open_items'] loop execute format('alter table public.%I enable row level security',t); if not exists(select 1 from pg_policies where schemaname='public' and tablename=t and policyname=t||'_phase4_member_select') then execute format('create policy %I on public.%I for select to authenticated using (public.is_active_org_member(%s))',t||'_phase4_member_select',t,case when t='sales_invoice_lines' then '(select i.organization_id from public.sales_invoices i where i.id=invoice_id)' when t='purchase_bill_lines' then '(select b.organization_id from public.purchase_bills b where b.id=bill_id)' else 'organization_id' end); end if; end loop; end $$;
revoke all on public.customers,public.suppliers,public.sales_invoices,public.sales_invoice_lines,public.purchase_bills,public.purchase_bill_lines,public.open_items from anon;
grant select on public.customers,public.suppliers,public.sales_invoices,public.sales_invoice_lines,public.purchase_bills,public.purchase_bill_lines,public.open_items to authenticated;
create or replace function public.ensure_business_document_sequences(p_organization_id uuid) returns void language plpgsql security definer set search_path=pg_catalog,public as $$ begin perform public.assert_accounting_owner(p_organization_id); insert into public.document_sequences(organization_id,document_type,prefix) values(p_organization_id,'purchase_bill','BILL-') on conflict (organization_id,branch_id,document_type,financial_year_id) do nothing; end; $$;
revoke all on function public.ensure_business_document_sequences(uuid) from public,anon;
grant execute on function public.ensure_business_document_sequences(uuid) to authenticated;
